package com.ifound;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import jakarta.inject.Inject;
import jakarta.ws.rs.*;
import jakarta.ws.rs.core.MediaType;
import java.util.*;
import java.time.Instant;

@Path("/api") @Produces(MediaType.APPLICATION_JSON) @Consumes(MediaType.APPLICATION_JSON)
public class BusinessResource {
 @Inject BusinessStore store;@Inject AuthService auth;@Inject ObjectMapper mapper;
 @HeaderParam("Authorization") String authorization;@HeaderParam("X-Session-Token") String token;
 AuthService.User user(){return auth.user(authorization,token);}
 Long revision(JsonNode input){if(input==null||!input.isObject()||!input.has("revision")||!input.get("revision").canConvertToLong()||!input.get("revision").isIntegralNumber()||input.get("revision").asLong()<0)throw new BadRequestException("A valid revision is required.");return input.get("revision").asLong();}
 ArrayNode list(String key,String query,int offset,int limit)throws Exception{user();if(offset<0||limit<1||limit>1000)throw new BadRequestException("Use offset >= 0 and limit 1–1000.");var out=mapper.createArrayNode();int skipped=0;for(var r:store.snapshot().workspace().withArray(key)){if(query!=null&&!r.path("name").asText().toLowerCase(Locale.ROOT).contains(query.toLowerCase(Locale.ROOT)))continue;if(skipped++<offset)continue;if(out.size()<limit)out.add(r);}return out;}
 @GET @Path("/customers") public JsonNode customers(@QueryParam("q")String q,@DefaultValue("0")@QueryParam("offset")int offset,@DefaultValue("100")@QueryParam("limit")int limit)throws Exception{return list("customers",q,offset,limit);}
 @GET @Path("/customers/{id}") public JsonNode customer(@PathParam("id")String id)throws Exception{user();return ComplianceEngine.find(store.snapshot().workspace(),"customers",id);}
 @POST @Path("/customers") public BusinessStore.Outcome createCustomer(JsonNode request)throws Exception{var u=user();auth.write(u);String id=UUID.randomUUID().toString();return store.mutate(revision(request),u,"CUSTOMER_CREATED",id,data->{var c=ComplianceEngine.customer(mapper,request,id);ComplianceEngine.prepend(data.withArray("customers"),c);return ComplianceEngine.screen(mapper,data,c);});}
 @POST @Path("/screenings") public BusinessStore.Outcome screening(JsonNode request)throws Exception{return createCustomer(request);}
 @PUT @Path("/customers/{id}") public BusinessStore.Outcome updateCustomer(@PathParam("id")String id,JsonNode request)throws Exception{var u=user();auth.write(u);return store.mutate(revision(request),u,"CUSTOMER_UPDATED",id,data->{var old=ComplianceEngine.find(data,"customers",id);var c=ComplianceEngine.customer(mapper,request,id);c.set("createdAt",old.has("createdAt")?old.get("createdAt"):c.get("createdAt"));old.removeAll();old.setAll(c);return ComplianceEngine.screen(mapper,data,old);});}
 @POST @Path("/customers/{id}/screen") public BusinessStore.Outcome rescreen(@PathParam("id")String id,JsonNode request)throws Exception{var u=user();auth.write(u);return store.mutate(revision(request),u,"CUSTOMER_SCREENED",id,data->ComplianceEngine.screen(mapper,data,ComplianceEngine.find(data,"customers",id)));}
 @DELETE @Path("/customers/{id}") public BusinessStore.Outcome deleteCustomer(@PathParam("id")String id,@QueryParam("revision")Long expected)throws Exception{var u=user();auth.admin(u);if(expected==null)throw new BadRequestException("revision is required.");return store.mutate(expected,u,"CUSTOMER_DELETED",id,data->{ComplianceEngine.find(data,"customers",id);for(var t:data.withArray("transactions"))if(t.path("customerId").asText().equals(id))throw new WebApplicationException("Customers with recorded transactions cannot be deleted.",409);remove(data.withArray("customers"),id);return mapper.createObjectNode().put("deleted",id);});}
 static void remove(ArrayNode list,String id){for(int i=0;i<list.size();i++)if(list.get(i).path("id").asText().equals(id)){list.remove(i);return;}}
 @GET @Path("/watchlists") public JsonNode watchlists(@QueryParam("q")String q,@DefaultValue("0")@QueryParam("offset")int offset,@DefaultValue("100")@QueryParam("limit")int limit)throws Exception{return list("watch",q,offset,limit);}
 @GET @Path("/watchlists/{id}") public JsonNode watchRecord(@PathParam("id")String id)throws Exception{user();return ComplianceEngine.find(store.snapshot().workspace(),"watch",id);}
 @POST @Path("/watchlists/import") public BusinessStore.Outcome importWatch(JsonNode request)throws Exception{var u=user();auth.admin(u);var records=request.get("records");if(records==null||!records.isArray()||records.isEmpty()||records.size()>10000)throw new BadRequestException("Import 1–10,000 watchlist records.");return store.mutate(revision(request),u,"WATCHLIST_IMPORTED",records.size()+" records",data->{int added=0;var keys=new HashSet<String>();for(var r:data.withArray("watch"))keys.add(watchKey(r));for(var r:records){var w=mapper.createObjectNode();w.put("id",UUID.randomUUID().toString());w.put("name",ComplianceEngine.required(r,"name",200));w.put("country",ComplianceEngine.optional(r,"country",100));String dob=ComplianceEngine.optional(r,"dob",10);ComplianceEngine.dob(dob);w.put("dob",dob);String source=ComplianceEngine.optional(r,"source",200);w.put("source",source.isEmpty()?"Uploaded watchlist":source);ComplianceEngine.watchDetails(r,w);if(keys.add(watchKey(w))){data.withArray("watch").add(w);added++;}}return mapper.createObjectNode().put("imported",added).put("duplicates",records.size()-added);});}
 String watchKey(JsonNode r){return (r.path("name").asText()+"|"+r.path("country").asText()+"|"+r.path("dob").asText()+"|"+r.path("source").asText()).toLowerCase(Locale.ROOT);}
 @POST @Path("/watchlists") public BusinessStore.Outcome createWatch(JsonNode request)throws Exception{ObjectNode wrapper=mapper.createObjectNode();wrapper.set("revision",request.get("revision"));wrapper.putArray("records").add(request);return importWatch(wrapper);}
 @PUT @Path("/watchlists/{id}") public BusinessStore.Outcome updateWatch(@PathParam("id")String id,JsonNode request)throws Exception{var u=user();auth.admin(u);return store.mutate(revision(request),u,"WATCHLIST_UPDATED",id,data->{var w=ComplianceEngine.find(data,"watch",id);w.put("name",ComplianceEngine.required(request,"name",200));w.put("country",ComplianceEngine.optional(request,"country",100));String date=ComplianceEngine.optional(request,"dob",10);ComplianceEngine.dob(date);w.put("dob",date);w.put("source",ComplianceEngine.required(request,"source",200));ComplianceEngine.watchDetails(request,w);for(var other:data.withArray("watch"))if(other!=w&&watchKey(other).equals(watchKey(w)))throw new WebApplicationException("Duplicate watchlist record.",409);return w;});}
 @DELETE @Path("/watchlists/{id}") public BusinessStore.Outcome deleteWatch(@PathParam("id")String id,@QueryParam("revision")Long expected)throws Exception{var u=user();auth.admin(u);if(expected==null)throw new BadRequestException("revision is required.");return store.mutate(expected,u,"WATCHLIST_DELETED",id,data->{ComplianceEngine.find(data,"watch",id);remove(data.withArray("watch"),id);return mapper.createObjectNode().put("deleted",id);});}
 @GET @Path("/transactions") public JsonNode transactions(@QueryParam("q")String q,@DefaultValue("0")@QueryParam("offset")int offset,@DefaultValue("100")@QueryParam("limit")int limit)throws Exception{return list("transactions",q,offset,limit);}
 @GET @Path("/transactions/{id}") public JsonNode transaction(@PathParam("id")String id)throws Exception{user();return ComplianceEngine.find(store.snapshot().workspace(),"transactions",id);}
 @POST @Path("/transactions") public BusinessStore.Outcome transact(JsonNode request)throws Exception{var u=user();auth.write(u);return store.mutate(revision(request),u,"TRANSACTION_EVALUATED",request.path("customerId").asText(),data->ComplianceEngine.transaction(mapper,data,request));}
 @GET @Path("/alerts") public JsonNode alerts(@QueryParam("status")String status,@QueryParam("risk")String risk,@QueryParam("q")String q,@DefaultValue("0")@QueryParam("offset")int offset,@DefaultValue("100")@QueryParam("limit")int limit)throws Exception{user();if(offset<0||limit<1||limit>1000)throw new BadRequestException("Invalid pagination.");var out=mapper.createArrayNode();int index=0;for(var a:store.snapshot().workspace().withArray("alerts")){if(status!=null&&!status.equals(a.path("status").asText())||risk!=null&&!risk.equals(a.path("risk").asText())||q!=null&&!a.path("name").asText().toLowerCase(Locale.ROOT).contains(q.toLowerCase(Locale.ROOT)))continue;if(index++>=offset&&out.size()<limit)out.add(a);}return out;}
 @GET @Path("/alerts/{id}") public JsonNode alert(@PathParam("id")String id)throws Exception{user();return ComplianceEngine.find(store.snapshot().workspace(),"alerts",id);}
 @GET @Path("/alerts/{id}/reviews") public JsonNode reviews(@PathParam("id")String id)throws Exception{return alert(id).path("reviews");}
 @POST @Path("/alerts/{id}/reviews") public BusinessStore.Outcome review(@PathParam("id")String id,JsonNode request)throws Exception{var u=user();auth.write(u);String status=ComplianceEngine.required(request,"status",100),note=ComplianceEngine.required(request,"note",2000);if(!Set.of("Open","In review","Closed").contains(status))throw new BadRequestException("Invalid review status.");return store.mutate(revision(request),u,"ALERT_REVIEWED",id,data->{var a=ComplianceEngine.find(data,"alerts",id);a.put("status",status);var review=a.withArray("reviews").addObject();review.put("at",Instant.now().toString());review.put("status",status);review.put("note",note);review.put("reviewer",u.username());return a;});}
 @GET @Path("/rules") public JsonNode rules()throws Exception{user();return store.snapshot().workspace().get("rules");}
 @PUT @Path("/rules") public BusinessStore.Outcome updateRules(JsonNode request)throws Exception{var u=user();auth.admin(u);return store.mutate(revision(request),u,"RULES_UPDATED","rule settings",data->{if(!request.has("rules"))throw new BadRequestException("rules is required.");data.set("rules",request.get("rules"));return data.get("rules");});}
 @GET @Path("/dashboard") public JsonNode dashboard()throws Exception{user();var data=store.snapshot().workspace();var metrics=mapper.createObjectNode();metrics.put("customers",data.withArray("customers").size());metrics.put("transactions",data.withArray("transactions").size());metrics.put("watchlistRecords",data.withArray("watch").size());int open=0,high=0;for(var a:data.withArray("alerts"))if(!a.path("status").asText().equals("Closed")){open++;if(a.path("risk").asText().equals("High"))high++;}metrics.put("openAlerts",open);metrics.put("highRiskAlerts",high);return metrics;}
 @GET @Path("/audit") public JsonNode audit(@DefaultValue("100")@QueryParam("limit")int limit)throws Exception{auth.admin(user());return store.auditLog(limit);}
}
